import json,glob
def scan(kws,n=5):
    out=[]
    for fn in sorted(glob.glob('articles/2026/04/*/articles.jsonl')):
        try:
            for line in open(fn):
                try:a=json.loads(line)
                except:continue
                t=a.get('title') or ''
                if any(k in t.lower() for k in kws): out.append((a.get('date_publish') or '',t))
        except:pass
    seen=set();r=[]
    for d,t in out:
        if t not in seen:seen.add(t);r.append((d,t))
    return r[:n]
